def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    prev_bids = []
    dangerous_count = 0
    rich_threat = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 45.0:
                dangerous_count += 1
        if opp.get('budget', 0) >= 200 and opp.get('hp', 0) > 0:
            rich_threat = True

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    severe_need = hp <= 2 or no_water_days >= 2
    urgent_need = hp <= 4 or no_water_days >= 1
    tight_supply = supply <= 16.0
    loose_supply = supply >= 22.0

    if severe_need:
        bid = 66.0 if rich_threat else 58.0
    elif urgent_need and tight_supply:
        bid = 54.0 if highest_prev >= 50.0 else 46.0
    elif tight_supply:
        if dangerous_count >= 1:
            bid = 14.0
        else:
            bid = 24.0
    elif loose_supply:
        bid = 6.0 if hp > 6 else 12.0
    else:
        if highest_prev >= 60.0:
            bid = 8.0 if hp > 5 else 38.0
        elif highest_prev >= 40.0:
            bid = 12.0 if hp > 6 else 30.0
        else:
            bid = max(16.0, avg_prev + 2.0)

    if day >= 8:
        if hp > 5 and not severe_need:
            bid = min(bid, 16.0)
        else:
            bid = max(bid, 34.0)

    bid = min(float(bid), float(budget))
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = int(day_context['supply'])  # ensure int
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Base bid: moderate to secure water
    base_bid = min(budget, DAILY_SALARY * 0.4)

    # If desperate: low HP or no water days
    if hp <= 2 or no_water_days >= 2:
        return min(budget, DAILY_SALARY * 0.9)

    # Analyze opponents' previous bid patterns
    highest_prev = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            if prev['bid'] > highest_prev:
                highest_prev = prev['bid']

    # If opponents bid very high yesterday, they might repeat; undercut if we have HP
    if highest_prev >= DAILY_SALARY * 0.8 and hp > 3:
        # bid just below their minimum likely bid
        target = highest_prev * 0.7
        return min(budget, max(base_bid, target))
    elif highest_prev > 0:
        # match or slightly beat the highest opponent from yesterday
        return min(budget, max(base_bid, highest_prev * 0.9))

    # Default: increase as days pass to compete for limited water
    if day <= 3:
        return min(budget, DAILY_SALARY * 0.35)
    elif day <= 7:
        return min(budget, DAILY_SALARY * 0.45)
    else:
        return min(budget, DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    current_supply = day_context['supply']

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Critical survival: If HP is very low, bid aggressively
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Estimate total water requirement for all alive agents including myself
    total_required_water = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)

    # Adjust bid based on supply:
    # If supply is very high, competition is low, bid conservatively
    if current_supply >= total_required_water * 1.2:
        if my_status['hp'] > 5: # Healthy, can afford to save
            return min(my_status['budget'], max(DAILY_SALARY * 0.3, highest_prev_bid * 0.8 if highest_prev_bid else 0))
        else: # Not super healthy, still want water
            return min(my_status['budget'], max(DAILY_SALARY * 0.4, highest_prev_bid * 0.9 if highest_prev_bid else 0))

    # If supply is low, competition is high
    elif current_supply < total_required_water * 0.8:
        if my_status['hp'] <= 5: # Low HP, need to be aggressive
            return min(my_status['budget'], max(DAILY_SALARY * 0.85, highest_prev_bid * 1.15 if highest_prev_bid else 0))
        else: # Healthy, but supply is tight, so still be competitive
            return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid * 1.1 if highest_prev_bid else 0))

    # Default / Medium supply scenario
    else:
        # If highest previous bid was very high, competition is tough
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # Healthy, willing to back off to save budget
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else: # Not healthy, must compete
                return min(my_status['budget'], DAILY_SALARY * 0.9)
        # If highest previous bid was moderate
        elif highest_prev_bid > 0:
            # Bid slightly above highest previous bid, but not more than my salary limit
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
        # If no significant previous bids (e.g., first day or opponents bid very low)
        else:
            if my_status['hp'] <= 5: # Not healthy, need water
                return min(my_status['budget'], DAILY_SALARY * 0.7)
            else: # Healthy, bid moderately
                return min(my_status['budget'], DAILY_SALARY * 0.55)
